head.script:
scwin.onpageload = function() {
    var jsonData = [{
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "2222",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "3333",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "4444",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    dataList1.sort('col1', 1);
};
scwin.trigger2_onclick = function(e) {
    var options = {};
    options.sortIndex = "col1";
    options.sortOrder = "-1";
    dataList1.multisort(options);
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq(WebSquare.wUnit.getObjById('gridView1_column7').getElementsByTagName('td')[1]).hasClass('w2grid_head_sort_desc') == true;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
